function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 1000) return 'The tree has at most 1000 nodes.';
  if (values.some(v => v !== 0 && v !== 1)) return 'Every node value is 0 or 1.';
  // Walk the level order, carrying each node's path number, to check the 32-bit guarantee.
  const numbers = [root[0]];
  let next = 1;
  let sum = 0;
  for (let q = 0; q < numbers.length; q++) {
    let children = 0;
    for (let side = 0; side < 2 && next < root.length; side++) {
      const v = root[next++];
      if (v !== null) { numbers.push(numbers[q] * 2 + v); children++; }
    }
    if (children === 0) sum += numbers[q];
  }
  if (sum > 2147483647) return 'The sum must fit in a signed 32-bit integer.';
  return null;
}

