function sumRootToLeaf(root) {
  // Collect every root-to-leaf path as a string of bits, then parse each one.
  let total = 0;
  const stack = [[root, '']];
  while (stack.length) {
    const [node, bits] = stack.pop();
    const path = bits + node.val;
    if (!node.left && !node.right) total += parseInt(path, 2);
    if (node.left) stack.push([node.left, path]);
    if (node.right) stack.push([node.right, path]);
  }
  return total;
}

