function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  // Large trees sometimes start with a long chain of zeros: deep paths whose leading zeros keep the numbers small.
  const chain = size === 'large' && rand() < 0.4 ? 100 + Math.floor(rand() * 400) : 1;
  const nodes = [{ val: chain > 1 ? 0 : (rand() < 0.5 ? 0 : 1), left: null, right: null, depth: 0 }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: 0, left: null, right: null, depth: i });
  }
  // Below the chain the depth is capped, so every path value stays far below 2^31.
  const maxDepth = chain + (size === 'large' ? 15 : 12);
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    const depth = nodes[parent].depth + 1;
    nodes.push({ val: rand() < 0.5 ? 0 : 1, left: null, right: null, depth });
    if (depth < maxDepth) slots.push([i, 'left'], [i, 'right']);
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
